19: /**
20:  * A generic pair implementation that can be used to cumulatively aggregate a data structure during a promise pipeline.
21:  * <p>
22:  * This can sometimes be useful when collecting facts about something as part of a data stream without using mutable data structures.
23:  * <pre class="java">{@code
24:  * import ratpack.func.Pair;
25:  * import ratpack.exec.Promise;
26:  * import ratpack.test.embed.EmbeddedApp;
27:  *
28:  * import static org.junit.Assert.assertEquals;
29:  *
30:  * public class Example {
31:  *
32:  *   public static void main(String[] args) throws Exception {
33:  *     EmbeddedApp.fromHandler(ctx -> {
34:  *       int id = 1;
35:  *       int age = 21;
36:  *       String name = "John";
37:  *
38:  *       Promise.value(id)
39:  *         .map(idValue -> Pair.of(idValue, age))
40:  *         .flatMap(pair -> Promise.value(name).map(pair::nestRight))
41:  *         .then(pair -> {
42:  *           int receivedId = pair.left;
43:  *           int receivedAge = pair.right.right;
44:  *           String receivedName = pair.right.left;
45:  *           ctx.render(receivedName + " [" + receivedId + "] - age: " + receivedAge);
46:  *         });
47:  *     }).test(httpClient -> {
48:  *       assertEquals("John [1] - age: 21", httpClient.getText());
49:  *     });
50:  *   }
51:  * }
52:  * }</pre>
53:  * <p>
54:  *
55:  * @param <L> the left data type
56:  * @param <R> the right data type
57:  */
58: public final class Pair<L, R> {
59: 
60:   /**
61:    * The left item of the pair.
62:    */
63:   public final L left;
64: 
65:   /**
66:    * The right item of the pair.
67:    */
68:   public final R right;
69: 
70:   private Pair(L left, R right) {
71:     this.left = left;
72:     this.right = right;
73:   }
74: 
75:   /**
76:    * Creates a new pair.
77:    *
78:    * @param left the left item
79:    * @param right the right item
80:    * @param <L> the type of the left item
81:    * @param <R> the type of the right item
82:    * @return a new pair
83:    */
84:   public static <L, R> Pair<L, R> of(L left, R right) {
85:     return new Pair<>(left, right);
86:   }
87: 
88:   /**
89:    * The left item of the pair.
90:    *
91:    * @return the left item of the pair
92:    */
93:   public L getLeft() {
94:     return left;
95:   }
96: 
97:   /**
98:    * The right item of the pair.
99:    *
100:    * @return the right item of the pair
101:    */
102:   public R getRight() {
103:     return right;
104:   }
105: 
106:   /**
107:    * The left item of the pair.
108:    *
109:    * @return the left item of the pair
110:    */
111:   public L left() {
112:     return left;
113:   }
114: 
115:   /**
116:    * The right item of the pair.
117:    *
118:    * @return the right item of the pair
119:    */
120:   public R right() {
121:     return right;
122:   }
123: 
124:   /**
125:    * Replaces the left item with the given item.
126:    *
127:    * @param newLeft the replacement left side of the pair
128:    * @param <T> the new left type
129:    * @return a new pair, with the given item replacing the left of this
130:    */
131:   public <T> Pair<T, R> left(T newLeft) {
132:     return of(newLeft, right);
133:   }
134: 
135:   /**
136:    * Replaces the right item with the given item.
137:    *
138:    * @param newRight the replacement right side of the pair
139:    * @param <T> the new right type
140:    * @return a new pair, with the given item replacing the right of this
141:    */
142:   public <T> Pair<L, T> right(T newRight) {
143:     return of(left, newRight);
144:   }
145: 
146:   /**
147:    * Creates a new pair.
148:    *
149:    * @param left the left item
150:    * @param right the right item
151:    * @param <L> the type of the left item
152:    * @param <R> the type of the right item
153:    * @return a new pair
154:    */
155:   public static <L, R> Pair<L, R> pair(L left, R right) {
156:     return of(left, right);
157:   }
158: 
159:   /**
160:    * Creates a new pair, with {@code this} as the right item and the given value as the left.
161:    *
162:    * @param t the left value for the returned pair
163:    * @param <T> the type of the left value for the returned pair
164:    * @return a new pair, with {@code this} as the right item and the given value as the left
165:    */
166:   public <T> Pair<T, Pair<L, R>> pushLeft(T t) {
167:     return of(t, this);
168:   }
169: 
170:   /**
171:    * Creates a new pair, with {@code this} as the left item and the given value as the right.
172:    *
173:    * @param t the right value for the returned pair
174:    * @param <T> the type of the right value for the returned pair
175:    * @return a new pair, with {@code this} as the left item and the given value as the right
176:    */
177:   public <T> Pair<Pair<L, R>, T> pushRight(T t) {
178:     return of(this, t);
179:   }
180: 
181:   /**
182:    * Creates a new pair, with {@code pair(t, this.left)} as the left item and the the right value of {@code this} as the right.
183:    *
184:    * @param t the item to nest with the left item of {@code this} pair
185:    * @param <T> the type of item to nest with the left item of {@code this} pair
186:    * @return a new pair, with {@code pair(t, this.left)} as the left item and the the right value of {@code this} as the right
187:    */
188:   public <T> Pair<Pair<T, L>, R> nestLeft(T t) {
189:     return of(of(t, left), right);
190:   }
191: 
192:   /**
193:    * Creates a new pair, with {@code pair(t, this.right)} as the right item and the the left value of {@code this} as the left.
194:    *
195:    * @param t the item to nest with the right item of {@code this} pair
196:    * @param <T> the type of item to nest with the right item of {@code this} pair
197:    * @return a new pair, with {@code pair(t, this.right)} as the right item and the the left value of {@code this} as the left
198:    */
199:   public <T> Pair<L, Pair<T, R>> nestRight(T t) {
200:     return of(left, of(t, right));
201:   }
202: 
203:   /**
204:    * Creates a new pair, with the left item being the result of applying the given function to the left item of {@code this}.
205:    * <p>
206:    * The right value is unchanged.
207:    *
208:    * @param function a transformer for the left value
209:    * @param <T> the type of the new left value
210:    * @return a new pair, with the left item being the result of applying the given function to the left item of {@code this}
211:    * @throws Exception any thrown by {@code function}
212:    */
213:   public <T> Pair<T, R> mapLeft(Function<? super L, ? extends T> function) throws Exception {
214:     T t = function.apply(left);
215:     return of(t, right);
216:   }
217: 
218:   /**
219:    * Creates a new pair, with the right item being the result of applying the given function to the right item of {@code this}.
220:    * <p>
221:    * The left value is unchanged.
222:    *
223:    * @param function a transformer for the right value
224:    * @param <T> the type of the new right value
225:    * @return a new pair, with the right item being the result of applying the given function to the right item of {@code this}
226:    * @throws Exception any thrown by {@code function}
227:    */
228:   public <T> Pair<L, T> mapRight(Function<? super R, ? extends T> function) throws Exception {
229:     T t = function.apply(right);
230:     return of(left, t);
231:   }
232: 
233:   /**
234:    * Applies the given function to {@code this}, returning the result.
235:    *
236:    * @param function a function to apply to {@code this}
237:    * @param <T> the function result type
238:    * @return the result of applying {@code function} to {@code this}
239:    * @throws Exception any thrown by {@code function}
240:    */
241: 
242:   public <T> T map(Function<? super Pair<L, R>, ? extends T> function) throws Exception {
243:     return function.apply(this);
244:   }
245: 
246:   /**
247:    * Convenience function for returning the left item of a pair.
248:    *
249:    * @param <L> the type of the left item
250:    * @param <P> the pair type
251:    * @return a function that when applied to a pair returns the left item
252:    */
253:   public static <L, P extends Pair<L, ?>> Function<P, L> unpackLeft() {
254:     return pair -> pair.left;
255:   }
256: 
257:   /**
258:    * Convenience function for returning the right item of a pair.
259:    *
260:    * @param <R> the type of the right item
261:    * @param <P> the pair type
262:    * @return a function that when applied to a pair returns the right item
263:    */
264:   public static <R, P extends Pair<?, R>> Function<P, R> unpackRight() {
265:     return pair -> pair.right;
266:   }
267: 
268:   /**
269:    * A pair is equal if its left and right items are equal to the left and right items of {@code this} respectively.
270:    *
271:    * @param o the object to compare to
272:    * @return the equality
273:    */
274:   @Override
275:   public boolean equals(Object o) {
276:     if (this == o) {
277:       return true;
278:     }
279:     if (o == null || getClass() != o.getClass()) {
280:       return false;
281:     }
282: 
283:     Pair<?, ?> pair = (Pair<?, ?>) o;
284: 
285:     return !(left != null ? !left.equals(pair.left) : pair.left != null) && !(right != null ? !right.equals(pair.right) : pair.right != null);
286:   }
287: 
288:   /**
289:    * Hash code.
290:    *
291:    * @return hash code.
292:    */
293:   @Override
294:   public int hashCode() {
295:     int result = left != null ? left.hashCode() : 0;
296:     result = 31 * result + (right != null ? right.hashCode() : 0);
297:     return result;
298:   }
299: 
300:   /**
301:    * Returns "Pair[«left.toString()»,«right.toString()»].
302:    *
303:    * @return "Pair[«left.toString()»,«right.toString()»]
304:    */
305:   @Override
306:   public String toString() {
307:     return "Pair[" + left + "," + right + ']';
308:   }
309: 
310: }
