481:       return contentType.equalsIgnoreCase(parser.getContentType()) && parser.getOptsType().isInstance(parse.getOpts());
482:     }
483: 
484:     @Override
485:     public boolean equals(Object o) {
486:       if (this == o) {
487:         return true;
488:       }
489:       if (o == null || getClass() != o.getClass()) {
490:         return false;
491:       }
492: 
493:       ParserForParsePredicate that = (ParserForParsePredicate) o;
494:       return contentType.equalsIgnoreCase(that.contentType) && parse.equals(that.parse);
495:     }
