356:   public void error(Throwable throwable) {
357:     ServerErrorHandler serverErrorHandler = get(ServerErrorHandler.class);
358: 
359:     Throwable unpacked = unpackThrowable(throwable);
360: 
361:     InternalServerThrowableWrapper handledThrowable = getRequest().maybeGet(InternalServerThrowableWrapper.class);
362:     Throwable unwrappedThrowable = handledThrowable == null ? null : handledThrowable.getThrowable();
363:     if (unwrappedThrowable != null) {
364:       handleErrorHandlerThrowable(serverErrorHandler, unpacked, unwrappedThrowable);
365:     } else {
366:       getRequest().register(InternalServerThrowableWrapper.class, new InternalServerThrowableWrapper(unpacked));
367: 
368:       try {
369:         serverErrorHandler.error(this, unpacked);
370:       } catch (Throwable errorHandlerThrowable) {
371:         handleErrorHandlerThrowable(serverErrorHandler, unpacked, errorHandlerThrowable);
372:       }
373:     }
374:   }
