376:   private void handleErrorHandlerThrowable(ServerErrorHandler serverErrorHandler, Throwable unpacked, Throwable errorHandlerThrowable) {
377:     StringBuilder sb = new StringBuilder();
378:     String originalThrowableMessage = "Throwable thrown by error handler "
379:       + serverErrorHandler.toString()
380:       + " while handling throwable\nOriginal throwable: ";
381:     LOGGER.error(originalThrowableMessage, unpacked);
382:     sb.append(originalThrowableMessage).append("\n");
383:     for (StackTraceElement element : unpacked.getStackTrace()) {
384:       sb.append(element.toString()).append("\n");
385:     }
386:     sb.append("\n");
387: 
388:     String handlerThrowableMessage = "Error handler throwable: ";
389:     LOGGER.error(handlerThrowableMessage, errorHandlerThrowable);
390:     sb.append(handlerThrowableMessage).append("\n");
391:     for (StackTraceElement element : errorHandlerThrowable.getStackTrace()) {
392:       sb.append(element.toString()).append("\n");
393:     }
394: 
395:     Response response = requestConstants.response.status(500);
396:     if (getLaunchConfig().isReloadable()) {
397:       response.send(sb.toString());
398:     } else {
399:       response.send();
400:     }
401:   }
