437:     if (nextIndex >= nextHandlers.length) {
438:       context = parentContext;
439:       handler = exhausted;
440:     } else {
441:       handler = nextHandlers[nextIndex];
442:       context = createContext(registry, nextHandlers, nextIndex + 1, exhausted);
443:     }
444: 
445:     try {
