506:   private static class ParserForParsePredicate implements Predicate<Parser<?>> {
507:     private final Parse<?, ?> parse;
508:     private final String contentType;
509: 
510:     private ParserForParsePredicate(Parse<?, ?> parse, String contentType) {
511:       this.parse = parse;
512:       this.contentType = contentType;
513:     }
514: 
515:     @Override
516:     public boolean apply(Parser<?> parser) {
517:       return contentType.equalsIgnoreCase(parser.getContentType()) && parser.getOptsType().isInstance(parse.getOpts());
518:     }
519: 
520:     @Override
521:     public boolean equals(Object o) {
522:       if (this == o) {
523:         return true;
524:       }
525:       if (o == null || getClass() != o.getClass()) {
526:         return false;
527:       }
528: 
529:       ParserForParsePredicate that = (ParserForParsePredicate) o;
530:       return contentType.equalsIgnoreCase(that.contentType) && parse.equals(that.parse);
531:     }
532: 
533:     @Override
534:     public int hashCode() {
535:       int result = contentType.hashCode();
536:       result = 31 * result + parse.hashCode();
537:       return result;
538:     }
539:   }
