236:    *       }
237:    *     });
238:    *     assert result.rendered(String.class).equals("hello! from GET request");
239:    *
240:    *     result = UnitTest.handle(handler, new Action&lt;RequestFixture&gt;() {
241:    *       public void execute(RequestFixture fixture) {
242:    *         fixture.method("post");
243:    *       }
244:    *     });
