272:    * The order that types are specified is significant for wildcard matching.
273:    * The earliest registered type that matches the wildcard will be used.
274:    * <p>
275:    * <pre class="java">
276:    * import ratpack.handling.Handler;
277:    * import ratpack.handling.Context;
278:    * import ratpack.handling.ByContentSpec;
279:    * import ratpack.func.Action;
280:    *
281:    * import ratpack.test.UnitTest;
282:    * import ratpack.test.handling.HandlingResult;
283:    * import ratpack.test.handling.RequestFixture;
284:    *
285:    * public class Example {
286:    *
287:    *   public static class ContentNegotiatingHandler implements Handler {
288:    *     public void handle(final Context context) throws Exception {
289:    *       final String message = "hello!";
290:    *
291:    *       context.byContent(new Action&lt;ByContentSpec&gt;() {
292:    *         public void execute(ByContentSpec spec) {
293:    *           spec.json(new Handler() {
294:    *             public void handle(Context context) {
295:    *               context.render("{\"msg\": \"" + message + "\"}");
296:    *             }
297:    *           }).
298:    *           html(new Handler() {
299:    *             public void handle(Context context) {
300:    *               context.render("<p>" + message + "</p>");
301:    *             }
302:    *           });
303:    *         }
304:    *       });
305:    *     }
306:    *   }
307:    *
308:    *   public static void main(String[] args) {
309:    *     Handler handler = new ContentNegotiatingHandler();
310:    *
311:    *     HandlingResult result = UnitTest.handle(handler, new Action&lt;RequestFixture&gt;() {
312:    *       public void execute(RequestFixture fixture) {
313:    *         fixture.header("Accept", "application/json");
314:    *       }
315:    *     });
316:    *     assert result.rendered(String.class).equals("{\"msg\": \"hello!\"}");
317:    *     assert result.getHeaders().get("Content-Type").equals("application/json");
318:    *
319:    *     result = UnitTest.handle(handler, new Action&lt;RequestFixture&gt;() {
320:    *       public void execute(RequestFixture fixture) {
321:    *         fixture.header("Accept", "text/plain; q=1.0, text/html; q=0.8, application/json; q=0.7");
322:    *       }
323:    *     });
324:    *     assert result.rendered(String.class).equals("<p>hello!</p>");
325:    *     assert result.getHeaders().get("content-type").equals("text/html;charset=UTF-8");
326:    *   }
327:    *
328:    * }
