537:    *             } else {
538:    *               fulfiller.error(throwable);
539:    *             }
540:    *           }
541:    *         }
542:    *
543:    *         public void execute(final Fulfiller&lt;Integer&gt; fulfiller) {
544:    *           for (int i = 0; i < numJobs; ++i) {
545:    *             final int iteration = i;
546:    *
547:    *             context.fork(new Action&lt;Execution&gt;() {
548:    *               public void execute(Execution execution) throws Exception {
549:    *                 if (failOnIteration != null && failOnIteration.intValue() == iteration) {
550:    *                   throw new Exception("bang!");
551:    *                 } else {
552:    *                   completeJob(fulfiller);
553:    *                 }
554:    *               }
555:    *
556:    *
557:    *             }, new Action&lt;Throwable&gt;() {
558:    *               public void execute(Throwable throwable) {
559: *                    error.compareAndSet(null, throwable); // just take the first error
560:    *                 completeJob(fulfiller);
561:    *               }
562:    *             });
563:    *           }
564:    *         }
565:    *       }).then(new Action&lt;Integer&gt;() {
566:    *         public void execute(Integer integer) {
567:    *           context.render(integer.toString());
568:    *         }
569:    *       });
570:    *     }
571:    *   }
572:    *
573:    *   public static void main(String[] args) {
574:    *     HandlingResult result = UnitTest.handle(new ForkingHandler(), Actions.noop());
575:    *     assert result.rendered(String.class).equals("3");
576:    *
577:    *     result = UnitTest.handle(new ForkingHandler(), new Action&lt;RequestFixture&gt;() {
578:    *       public void execute(RequestFixture fixture) {
579:    *         fixture.pathBinding(Collections.singletonMap("failOn", "2"));
580:    *       }
581:    *     });
