51: @ChannelHandler.Sharable
52: public class NettyHandlerAdapter extends ChannelInboundHandlerAdapter {
53: 
54:   private static final AttributeKey<Action<Object>> CHANNEL_SUBSCRIBER_ATTRIBUTE_KEY = AttributeKey.valueOf("ratpack.subscriber");
55:   private static final AttributeKey<RequestBodyAccumulator> BODY_ACCUMULATOR_KEY = AttributeKey.valueOf(RequestBodyAccumulator.class.getName());
56: 
57:   private final static Logger LOGGER = LoggerFactory.getLogger(NettyHandlerAdapter.class);
58: 
59:   private final Handler[] handlers;
60: 
61:   private final DefaultContext.ApplicationConstants applicationConstants;
62: 
63:   private final Registry serverRegistry;
64:   private final boolean development;
65: 
66:   public NettyHandlerAdapter(Registry serverRegistry, Handler handler) throws Exception {
67:     this.handlers = ChainHandler.unpack(handler);
68:     this.serverRegistry = serverRegistry;
69:     this.applicationConstants = new DefaultContext.ApplicationConstants(this.serverRegistry, new DefaultRenderController(), serverRegistry.get(ExecController.class), Handlers.notFound());
70:     this.development = serverRegistry.get(ServerConfig.class).isDevelopment();
71:   }
72: 
73:   @Override
74:   public void channelActive(ChannelHandlerContext ctx) throws Exception {
75:     ctx.read();
76:     super.channelActive(ctx);
77:   }
78: 
79:   @Override
80:   public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
81:     if (msg instanceof HttpRequest) {
82:       newRequest(ctx, (HttpRequest) msg);
83:     } else if (msg instanceof HttpContent) {
84:       ((HttpContent) msg).touch();
85:       RequestBodyAccumulator bodyAccumulator = ctx.channel().attr(BODY_ACCUMULATOR_KEY).get();
86:       if (bodyAccumulator == null) {
87:         ((HttpContent) msg).release();
88:       } else {
89:         bodyAccumulator.add((HttpContent) msg);
90:       }
91:       if (msg instanceof LastHttpContent) {
92:         ctx.read();
93:       }
94:     } else {
95:       Action<Object> subscriber = ctx.channel().attr(CHANNEL_SUBSCRIBER_ATTRIBUTE_KEY).get();
96:       if (subscriber == null) {
97:         super.channelRead(ctx, msg);
98:       } else {
99:         subscriber.execute(msg);
100:       }
101:     }
102:   }
103: 
104:   private void newRequest(final ChannelHandlerContext ctx, final HttpRequest nettyRequest) throws Exception {
105:     if (!nettyRequest.decoderResult().isSuccess()) {
106:       sendError(ctx, HttpResponseStatus.BAD_REQUEST);
107:       return;
108:     }
109: 
110:     Headers requestHeaders = new NettyHeadersBackedHeaders(nettyRequest.headers());
111: 
112:     //Find the content length we will use this as an indicator of a body
113:     Long contentLength = HttpUtil.getContentLength(nettyRequest, -1L);
114:     String transferEncoding = requestHeaders.get(HttpHeaderNames.TRANSFER_ENCODING);
115: 
116:     //If there is a content length or transfer encoding that indicates there is a body
117:     boolean hasBody = (contentLength > 0) || (transferEncoding != null);
118: 
119:     RequestBody requestBody = hasBody ? new RequestBody(contentLength, nettyRequest, ctx) : null;
120: 
121:     final Channel channel = ctx.channel();
122: 
123:     if (requestBody != null) {
124:       channel.attr(BODY_ACCUMULATOR_KEY).set(requestBody);
125:     }
126:     InetSocketAddress remoteAddress = (InetSocketAddress) channel.remoteAddress();
127:     InetSocketAddress socketAddress = (InetSocketAddress) channel.localAddress();
128: 
129:     final DefaultRequest request = new DefaultRequest(
130:       Instant.now(),
131:       requestHeaders,
132:       nettyRequest.method(),
133:       nettyRequest.protocolVersion(),
134:       nettyRequest.uri(),
135:       remoteAddress,
136:       socketAddress,
137:       serverRegistry.get(ServerConfig.class),
138:       requestBody
139:     );
140:     final HttpHeaders nettyHeaders = new DefaultHttpHeaders(false);
141:     final MutableHeaders responseHeaders = new NettyHeadersBackedMutableHeaders(nettyHeaders);
142:     final AtomicBoolean transmitted = new AtomicBoolean(false);
143: 
144:     final DefaultResponseTransmitter responseTransmitter = new DefaultResponseTransmitter(transmitted, channel, nettyRequest, request, nettyHeaders, requestBody);
145: 
146:     ctx.channel().attr(DefaultResponseTransmitter.ATTRIBUTE_KEY).set(responseTransmitter);
147: 
148:     Action<Action<Object>> subscribeHandler = thing -> {
149:       transmitted.set(true);
150:       ctx.channel().attr(CHANNEL_SUBSCRIBER_ATTRIBUTE_KEY).set(thing);
151:     };
152: 
153:     final DefaultContext.RequestConstants requestConstants = new DefaultContext.RequestConstants(
154:       applicationConstants,
155:       request,
156:       channel,
157:       responseTransmitter,
158:       subscribeHandler
159:     );
160: 
161:     final Response response = new DefaultResponse(responseHeaders, ctx.alloc(), responseTransmitter);
162:     requestConstants.response = response;
163: 
164:     DefaultContext.start(channel.eventLoop(), requestConstants, serverRegistry, handlers, execution -> {
165:       if (requestBody != null) {
166:         requestBody.close();
167:         channel.attr(BODY_ACCUMULATOR_KEY).set(null);
168:       }
169: 
170:       if (!transmitted.get()) {
171:         Handler lastHandler = requestConstants.handler;
172:         StringBuilder description = new StringBuilder();
173:         description
174:           .append("No response sent for ")
175:           .append(request.getMethod().getName())
176:           .append(" request to ")
177:           .append(request.getUri());
178: 
179:         if (lastHandler != null) {
180:           description.append(" (last handler: ");
181: 
182:           if (lastHandler instanceof DescribingHandler) {
183:             ((DescribingHandler) lastHandler).describeTo(description);
184:           } else {
185:             DescribingHandlers.describeTo(lastHandler, description);
186:           }
187:           description.append(")");
188:         }
189: 
190:         String message = description.toString();
191:         LOGGER.warn(message);
192: 
193:         response.getHeaders().clear();
194: 
195:         ByteBuf body;
196:         if (development) {
197:           CharBuffer charBuffer = CharBuffer.wrap(message);
198:           body = ByteBufUtil.encodeString(ctx.alloc(), charBuffer, CharsetUtil.UTF_8);
199:           response.contentType(HttpHeaderConstants.PLAIN_TEXT_UTF8);
200:         } else {
201:           body = Unpooled.EMPTY_BUFFER;
202:         }
203: 
204:         response.getHeaders().set(HttpHeaderConstants.CONTENT_LENGTH, body.readableBytes());
205:         responseTransmitter.transmit(HttpResponseStatus.INTERNAL_SERVER_ERROR, body);
206:       }
207:     });
208:   }
209: 
210:   @Override
211:   public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
212:     if (!isIgnorableException(cause)) {
213:       LOGGER.error("", cause);
214:       if (ctx.channel().isActive()) {
215:         sendError(ctx, HttpResponseStatus.INTERNAL_SERVER_ERROR);
216:       }
217:     }
218:   }
219: 
220:   @Override
221:   public void channelWritabilityChanged(ChannelHandlerContext ctx) throws Exception {
222:     ctx.channel().attr(DefaultResponseTransmitter.ATTRIBUTE_KEY).get().writabilityChanged();
223:   }
224: 
225:   private boolean isIgnorableException(Throwable throwable) {
226:     if (throwable instanceof ClosedChannelException) {
227:       return true;
228:     } else if (throwable instanceof IOException) {
229:       // There really does not seem to be a better way of detecting this kind of exception
230:       String message = throwable.getMessage();
231:       return message != null && message.endsWith("Connection reset by peer");
232:     } else {
233:       return false;
234:     }
235:   }
236: 
237:   public static void sendError(ChannelHandlerContext ctx, HttpResponseStatus status) {
238:     FullHttpResponse response = new DefaultFullHttpResponse(
239:       HttpVersion.HTTP_1_1, status, Unpooled.copiedBuffer("Failure: " + status.toString() + "\r\n", CharsetUtil.UTF_8));
240:     response.headers().set(HttpHeaderConstants.CONTENT_TYPE, HttpHeaderConstants.PLAIN_TEXT_UTF8);
241: 
242:     // Close the connection as soon as the error message is sent.
243:     ctx.writeAndFlush(response).addListener(ChannelFutureListener.CLOSE);
244:   }
245: }
