45:     SecretKeySpec secretKeySpec = new SecretKeySpec(key, macAlgorithm);
46:     Mac mac = Mac.getInstance(macAlgorithm);
47:     mac.init(secretKeySpec);
48:     byte[] signed = mac.doFinal(message.getBytes("utf-8"));
49:     return BaseEncoding.base64Url().encode(signed);
50:   }
