92:  *                   sessionData.set(pathTokens.get("name"), pathTokens.get("value"));
93:  *                   ctx.render("ok");
94:  *                 })
95:  *             )
96:  *             .get("get/:name", ctx -> {
97:  *               ctx.get(Session.class).getData()
98:  *                 .map(d -> d.require(ctx.getPathTokens().get("name")))
99:  *                 .then(ctx::render);
100:  *             })
101:  *         )
102:  *     ).test(httpClient -> {
103:  *       assertEquals("ok", httpClient.getText("set/foo/bar"));
104:  *       assertEquals("bar", httpClient.getText("get/foo"));
105:  *
106:  *       assertEquals("ok", httpClient.getText("set/foo/baz"));
107:  *       assertEquals("baz", httpClient.getText("get/foo"));
108:  *     });
109:  *   }
110:  * }
111:  * }</pre>
