32: public class TargetFileStaticAssetRequestHandler implements Handler {
33: 
34:   private final List<Handler> delegate;
35: 
36:   public TargetFileStaticAssetRequestHandler(Handler delegate) {
37:     this.delegate = ImmutableList.of(delegate);
38:   }
39: 
40:   public void handle(Exchange exchange) {
41:     FileSystemBinding fileSystemBinding = exchange.get(FileSystemBinding.class);
42: 
43:     Request request = exchange.getRequest();
44: 
45:     String path = request.getPath();
46:     PathBinding pathBinding = exchange.maybeGet(PathBinding.class);
47:     if (pathBinding != null) {
48:       path = pathBinding.getPastBinding();
49:     }
50: 
51:     // Decode the path.
52:     try {
53:       path = new URI(path).getPath();
54:     } catch (URISyntaxException e) {
55:       throw new RuntimeException(e);
56:     }
57: 
58:     // Convert file separators.
59:     path = path.replace('/', File.separatorChar);
60: 
61:     if (
62:         path.contains(File.separator + '.')
63:             || path.contains('.' + File.separator)
64:             || path.startsWith(".") || path.endsWith(".")
65:         ) {
66:       return;
67:     }
68: 
69:     FileSystemBinding newBinding = fileSystemBinding.binding(path);
70:     ServiceRegistry newContext = exchange.getContext().plus(FileSystemBinding.class, newBinding);
71:     exchange.insert(newContext, delegate);
72:   }
73: }
