28: public class ScriptBackedHandler implements Handler {
29: 
30:   private final Factory<Handler> reloadHandler;
31:   private final Path script;
32: 
33:   public ScriptBackedHandler(Path script, boolean reloadable, BiFunction<? super Path, ? super String, ? extends Handler> capture) throws Exception {
34:     this.script = script;
35:     this.reloadHandler = new ReloadableFileBackedFactory<>(script, reloadable, (file, bytes) -> {
36:       String string = bytes.toString(CharsetUtil.UTF_8);
37:       return capture.apply(script, string);
38:     });
39: 
40:     if (reloadable) {
41:       new Thread(() -> {
42:         try {
43:           reloadHandler.create();
44:         } catch (Exception ignore) {
45:           // ignore
46:         }
47:       }).run();
48:     } else {
49:       reloadHandler.create();
50:     }
51:   }
52: 
53:   public void handle(Context context) throws Exception {
54:     Handler handler = reloadHandler.create();
55:     if (handler == null) {
56:       context.getResponse().send("script file does not exist:" + script.toAbsolutePath());
57:     } else {
58:       handler.handle(context);
59:     }
60:   }
61: 
62: }
