19: import io.netty.buffer.ByteBuf;
20: import io.netty.buffer.UnpooledByteBufAllocator;
21: import ratpack.registry.Registry;
22: import ratpack.server.ReloadInformant;
23: import ratpack.util.internal.content;
24: 
25: import java.io.IOException;
26: import java.nio.file.Files;
27: import java.nio.file.Path;
28: import java.nio.file.attribute.FileTime;
29: import java.util.concurrent.atomic.AtomicReference;
30: import java.util.concurrent.locks.Lock;
31: import java.util.concurrent.locks.ReentrantLock;
32: 
33: import static ratpack.util.Exceptions.uncheck;
34: 
35: public class FileBackedReloadInformant implements ReloadInformant {
36:   private final Path file;
37:   private final Lock lock = new ReentrantLock();
38:   private final AtomicReference<FileTime> lastModifiedHolder = new AtomicReference<>(null);
39:   private final AtomicReference<ByteBuf> contentHolder = new AtomicReference<>();
40: 
41:   public FileBackedReloadInformant(Path file) {
42:     this.file = file;
43:     load();
44:   }
45: 
46:   private void load() {
47:     lock.lock();
48:     try {
49:       FileTime lastModifiedTime = Files.getLastModifiedTime(file);
50:       ByteBuf bytes = content.content(UnpooledByteBufAllocator.DEFAULT, file);
51: 
52:       this.lastModifiedHolder.set(lastModifiedTime);
53:       this.contentHolder.set(bytes);
54:     } catch (Exception e) {
55:       throw uncheck(e);
56:     } finally {
57:       lock.unlock();
58:     }
59:   }
60: 
61:   @Override
62:   public boolean shouldReload(Registry registry) {
63:     // If the file disappeared, wait a little for it to appear
64:     int i = 10;
65:     while (!Files.exists(file) && --i > 0) {
66:       try {
67:         Thread.sleep(100);
68:       } catch (InterruptedException e) {
69:         throw uncheck(e);
70:       }
71:     }
72: 
73:     if (!Files.exists(file)) {
74:       return false;
75:     }
76: 
77:     try {
78:       return reloadNeeded();
79:     } catch (Exception e) {
80:       throw uncheck(e);
81:     }
82:   }
83: 
84:   @Override
85:   public String toString() {
86:     return "file-backed reload informant: " + file.toString();
87:   }
88: 
89:   private boolean reloadNeeded() throws IOException {
90:     return !isBytesAreSame();
91:   }
92: 
93:   private boolean isBytesAreSame() throws IOException {
94:     lock.lock();
95:     try {
96:       ByteBuf existing = contentHolder.get();
97:       //noinspection SimplifiableIfStatement
98:       if (existing == null) {
99:         return false;
100:       }
101: 
102:       return content.content(UnpooledByteBufAllocator.DEFAULT, file).equals(existing);
103:     } finally {
104:       lock.unlock();
105:     }
106:   }
107: }
