34: public class FileBackedReloadInformant implements ReloadInformant {
35:   private final Path file;
36:   private final Lock lock = new ReentrantLock();
37:   private final AtomicReference<FileTime> lastModifiedHolder = new AtomicReference<>(null);
38:   private final AtomicReference<ByteBuf> contentHolder = new AtomicReference<>();
39: 
40:   public FileBackedReloadInformant(Path file) {
41:     this.file = file;
42:     load();
43:   }
44: 
45:   private void load() {
46:     lock.lock();
47:     try {
48:       FileTime lastModifiedTime = Files.getLastModifiedTime(file);
49:       ByteBuf content = content.content(UnpooledByteBufAllocator.DEFAULT, file);
50: 
51:       this.lastModifiedHolder.set(lastModifiedTime);
52:       this.contentHolder.set(content);
53:     } catch (Exception e) {
54:       throw uncheck(e);
55:     } finally {
56:       lock.unlock();
57:     }
58:   }
59: 
60:   @Override
61:   public boolean shouldReload(Registry registry) {
62:     // If the file disappeared, wait a little for it to appear
63:     int i = 10;
64:     while (!Files.exists(file) && --i > 0) {
65:       try {
66:         Thread.sleep(100);
67:       } catch (InterruptedException e) {
68:         throw uncheck(e);
69:       }
70:     }
71: 
72:     if (!Files.exists(file)) {
73:       return false;
74:     }
75: 
76:     try {
77:       return reloadNeeded();
78:     } catch (Exception e) {
79:       throw uncheck(e);
80:     }
81:   }
82: 
83:   @Override
84:   public String toString() {
85:     return "file-backed reload informant: " + file.toString();
86:   }
87: 
88:   private boolean reloadNeeded() throws IOException {
89:     return !isBytesAreSame();
90:   }
91: 
92:   private boolean isBytesAreSame() throws IOException {
93:     lock.lock();
94:     try {
95:       ByteBuf existing = contentHolder.get();
96:       //noinspection SimplifiableIfStatement
97:       if (existing == null) {
98:         return false;
99:       }
100: 
101:       return ratpack.util.internal.content.content(UnpooledByteBufAllocator.DEFAULT, file).equals(existing);
102:     } finally {
103:       lock.unlock();
104:     }
105:   }
106: }
