34: public class ExecutionBacking {
35: 
36:   final static Logger LOGGER = LoggerFactory.getLogger(Execution.class);
37: 
38:   private final List<ExecInterceptor> interceptors = new LinkedList<>();
39:   private final List<AutoCloseable> closeables = new LinkedList<>();
40:   private final Deque<Runnable> segments = new ConcurrentLinkedDeque<>();
41:   private final ExecController controller;
42:   private final Action<? super Throwable> onError;
43:   private final Action<? super Execution> onComplete;
44:   private final ThreadLocal<ExecutionBacking> threadBinding;
45: 
46:   private final AtomicBoolean active = new AtomicBoolean();
47:   private boolean streaming;
48:   private boolean waiting;
49:   private boolean done;
50: 
51:   private final Execution execution;
52: 
53:   public ExecutionBacking(ExecController controller, ThreadLocal<ExecutionBacking> threadBinding, Action<? super Execution> action, Action<? super Throwable> onError, Action<? super Execution> onComplete) {
54:     this.controller = controller;
55:     this.onError = onError;
56:     this.onComplete = onComplete;
57:     this.threadBinding = threadBinding;
58:     this.execution = new DefaultExecution(controller, closeables);
59: 
60:     segments.addLast(new UserCodeSegment(action));
61:     drain();
62:   }
63: 
64:   public Execution getExecution() {
65:     return execution;
66:   }
67: 
68:   public ExecController getController() {
69:     return controller;
70:   }
71: 
72:   public List<ExecInterceptor> getInterceptors() {
73:     return interceptors;
74:   }
75: 
76:   public void join(final Action<? super Execution> action) {
77:     segments.addFirst(new UserCodeSegment(action));
78:     waiting = false;
79:     drain();
80:   }
81: 
82:   public void continueVia(final Runnable runnable) {
83:     segments.addLast(new Runnable() {
84:       @Override
85:       public void run() {
86:         waiting = true;
87:         runnable.run();
88:       }
89:     });
90:   }
91: 
