104:   private void drain() {
105:     assertNotDone();
106:     if (!waiting && !segments.isEmpty()) {
107:       if (active.compareAndSet(false, true)) {
108:         if (controller.isManagedThread()) {
109:           threadBinding.set(this);
110:           try {
111:             Runnable segment = segments.poll();
112:             while (segment != null) {
113:               segment.run();
114:               if (waiting) { // the segment initiated an async op
115:                 break;
116:               } else {
117:                 segment = segments.poll();
118:                 if (segment == null && !streaming) { // not waiting, not streaming and no more segments, we are done
119:                   done();
120:                 }
121:               }
122:             }
123:           } finally {
124:             threadBinding.remove();
125:             active.set(false);
126:           }
127:           if (waiting) {
128:             drain();
129:           }
130:         } else {
131:           active.set(false);
132:           controller.getEventLoopGroup().submit(this::drain);
133:         }
134:       }
135:     }
136:   }
137: 
138:   private void done() {
139:     done = true;
140:     try {
141:       onComplete.execute(getExecution());
142:     } catch (Exception e) {
143:       LOGGER.warn("exception raised during onComplete action", e);
144:     }
145: 
146:     for (AutoCloseable closeable : closeables) {
147:       try {
148:         closeable.close();
149:       } catch (Exception e) {
150:         LOGGER.warn(String.format("exception raised by closeable %s", closeable), e);
151:       }
152:     }
153:   }
