171:     private final Action<? super Execution> action;
172: 
173:     public UserCodeSegment(Action<? super Execution> action) {
174:       this.action = action;
175:     }
176: 
177:     @Override
178:     public void run() {
179:       try {
180:         intercept(ExecInterceptor.ExecType.COMPUTE, interceptors, action);
181:       } catch (final Throwable e) {
182:         segments.clear();
183:         segments.addFirst(() -> {
184:           try {
185:             onError.execute(e);
186:           } catch (final Throwable errorHandlerException) {
187:             segments.addFirst(new UserCodeSegment(Action.throwException(errorHandlerException)));
188:           }
189:         });
190:       }
191:     }
192:   }
