31: 
32: import java.nio.file.Files;
33: import java.nio.file.Path;
34: import java.nio.file.attribute.BasicFileAttributes;
35: import java.util.Date;
36: import java.util.Optional;
37: 
38: import static io.netty.handler.codec.http.HttpResponseStatus.NOT_MODIFIED;
39: 
40: public class FileRenderer extends RendererSupport<Path> {
41: 
42:   private final boolean cacheMetadata;
43: 
44:   public FileRenderer(boolean cacheMetadata) {
45:     this.cacheMetadata = cacheMetadata;
46:   }
47: 
48:   private static final Cache<Path, Optional<BasicFileAttributes>> CACHE = Caffeine.newBuilder()
49:     .maximumSize(10000)
50:     .build();
51: 
52:   @Override
53:   public void render(Context context, Path targetFile) throws Exception {
54:     readAttributes(targetFile, cacheMetadata, attributes -> {
55:       if (attributes == null || !attributes.isRegularFile()) {
56:         context.clientError(404);
57:       } else {
58:         sendFile(context, targetFile, attributes);
59:       }
60:     });
61:   }
62: 
63:   public static void sendFile(Context context, Path file, BasicFileAttributes attributes) {
64:     if (!context.getRequest().getMethod().isGet()) {
65:       context.clientError(405);
66:       return;
67:     }
68: 
69:     Date date = new Date(attributes.lastModifiedTime().toMillis());
70: 
71:     context.lastModified(date, () -> {
72:       final String ifNoneMatch = context.getRequest().getHeaders().get(HttpHeaderNames.IF_NONE_MATCH);
73:       Response response = context.getResponse();
74:       if (ifNoneMatch != null && ifNoneMatch.trim().equals("*")) {
75:         response.status(NOT_MODIFIED.code()).send();
76:         return;
77:       }
78: 
79:       response.contentTypeIfNotSet(() -> context.get(MimeTypes.class).getContentType(file.getFileName().toString()));
80:       response.getHeaders().set(HttpHeaderConstants.CONTENT_LENGTH, Long.toString(attributes.size()));
81:       try {
82:         response.sendFile(file);
83:       } catch (Exception e) {
84:         throw Exceptions.uncheck(e);
85:       }
86:     });
87:   }
88: 
89:   private static Factory<BasicFileAttributes> getter(Path file) {
90:     return () -> {
91:       if (Files.exists(file)) {
92:         return Files.readAttributes(file, BasicFileAttributes.class);
93:       } else {
94:         return null;
95:       }
96:     };
97:   }
98: 
99:   public static void readAttributes(Path file, boolean cacheMetadata, Action<? super BasicFileAttributes> then) throws Exception {
100:     if (cacheMetadata) {
101:       Optional<BasicFileAttributes> basicFileAttributes = CACHE.getIfPresent(file);
102:       if (basicFileAttributes == null) {
103:         Blocking.get(getter(file)).then(a -> {
104:           CACHE.put(file, Optional.ofNullable(a));
105:           then.execute(a);
106:         });
107:       } else {
108:         then.execute(basicFileAttributes.orElse(null));
109:       }
110:     } else {
111:       Blocking.get(getter(file)).then(then);
112:     }
113:   }
114: 
115: }
