130:   private static class ChainIndex implements Iterator<Handler> {
131:     final Handler[] handlers;
132:     Registry registry;
133:     final boolean first;
134:     int i;
135: 
136:     private ChainIndex(Handler[] handlers, Registry registry, boolean first) {
137:       this.handlers = handlers;
138:       this.registry = registry;
139:       this.first = first;
140:     }
141: 
142:     public Handler next() {
143:       return handlers[i++];
144:     }
145: 
146:     @Override
147:     public boolean hasNext() {
148:       return i < handlers.length;
149:     }
150:   }
