156:   public static void start(EventLoop eventLoop, final RequestConstants requestConstants, Registry registry, Handler[] handlers, Action<? super Execution> onComplete) {
157:     ChainIndex index = new ChainIndex(handlers, registry, true);
158:     requestConstants.indexes.push(index);
159: 
160:     DefaultContext context = new DefaultContext(requestConstants);
161:     requestConstants.context = context;
162: 
163:     context.pathBindings = new PathBindingStorage(new RootPathBinding(requestConstants.request.getPath()));
164: 
165:     requestConstants.applicationConstants.execController.fork()
166:       .onError(throwable -> requestConstants.context.error(throwable instanceof HandlerException ? throwable.getCause() : throwable))
167:       .onComplete(onComplete)
168:       .register(s -> s
169:         .add(Context.TYPE, context)
170:         .add(Request.TYPE, requestConstants.request)
171:         .add(Response.TYPE, requestConstants.response)
172:         .add(PathBindingStorage.TYPE, context.pathBindings)
173:         .addLazy(RequestId.TYPE, () -> registry.get(RequestId.Generator.TYPE).generate(requestConstants.request))
174:       )
175:       .eventLoop(eventLoop)
176:       .onStart(e -> DefaultRequest.setDelegateRegistry(requestConstants.request, e))
177:       .start(e -> {
178:         requestConstants.execution = e;
179:         context.joinedRegistry = new ContextRegistry(context).join(requestConstants.execution);
180:         context.next();
181:       });
182:   }
