233:   public void next() {
234:     Handler handler = null;
235: 
236:     ChainIndex index = requestConstants.indexes.peek();
237:     while (handler == null) {
238:       if (index.hasNext()) {
239:         handler = index.next();
240:         if (handler.getClass().equals(ChainHandler.class)) {
241:           requestConstants.indexes.push(new ChainIndex(((ChainHandler) handler).getHandlers(), getCurrentRegistry(), false));
242:           index = requestConstants.indexes.peek();
243:           handler = null;
244:         }
245:       } else if (index.first) {
246:         handler = requestConstants.applicationConstants.end;
247:       } else {
248:         requestConstants.indexes.pop();
249:         index = requestConstants.indexes.peek();
250:       }
251:     }
252: 
253:     try {
254:       requestConstants.handler = handler;
255:       handler.handle(this);
256:     } catch (Throwable e) {
257:       if (e instanceof HandlerException) {
258:         throw (HandlerException) e;
259:       } else {
260:         throw new HandlerException(e);
261:       }
262:     }
263:   }
