317:   public <T, O> T parse(TypedData body, Parse<T, O> parse) throws Exception {
318:     Function<Parser<?>, T> parserPredicate;
319:     List<Parser<?>> parsers = Lists.newArrayList();
320:     if (parse.getOpts().isPresent()) {
321:       parserPredicate = parser -> {
322:         if (parser.getOptsType().isInstance(parse.getOpts().get())) {
323:           parsers.add(parser);
324:           Parser<O> cast = Types.cast(parser);
325:           return cast.parse(DefaultContext.this, body, parse);
326:         }
327:         return null;
328:       };
329:     } else {
330:       parserPredicate = parser -> {
331:         parsers.add(parser);
332:         Parser<O> cast = Types.cast(parser);
333:         return cast.parse(DefaultContext.this, body, parse);
334:       };
335:     }
336: 
337:     return joinedRegistry
338:       .first(PARSER_TYPE_TOKEN, parserPredicate)
339:       .orElseThrow(() -> new NoSuchParserException(parse.getType(), parse.getOpts().orElse(null), body.getContentType().getType(), parsers));
