382:     long lastModifiedSecs = date.getTime() / 1000;
383: 
384:     if (ifModifiedSinceHeader != null) {
385:       long time = ifModifiedSinceHeader.getTime();
386:       long ifModifiedSinceSecs = time / 1000;
387: 
388:       if (lastModifiedSecs == ifModifiedSinceSecs) {
389:         requestConstants.response.status(NOT_MODIFIED.code()).send();
390:         return;
391:       }
392:     }
393: 
394:     requestConstants.response.getHeaders().setDate(HttpHeaderConstants.LAST_MODIFIED, date);
395:     runnable.run();
396:   }
