398:   public void error(Throwable throwable) {
399:     ServerErrorHandler serverErrorHandler = get(ServerErrorHandler.TYPE);
400:     throwable = unpackThrowable(throwable);
401: 
402:     ThrowableHolder throwableHolder = getRequest().maybeGet(ThrowableHolder.TYPE).orElse(null);
403:     if (throwableHolder == null) {
404:       getRequest().add(ThrowableHolder.TYPE, new ThrowableHolder(throwable));
405: 
406:       try {
407:         serverErrorHandler.error(this, throwable);
408:       } catch (Throwable errorHandlerThrowable) {
409:         onErrorHandlerError(serverErrorHandler, throwable, errorHandlerThrowable);
410:       }
411:     } else {
412:       onErrorHandlerError(serverErrorHandler, throwableHolder.getThrowable(), throwable);
413:     }
414:   }
