416:   private void onErrorHandlerError(ServerErrorHandler serverErrorHandler, Throwable original, Throwable errorHandlerThrowable) {
417:     String msg = "Throwable thrown by error handler " + serverErrorHandler + " while handling throwable\n"
418:       + "Original throwable: " + getStackTraceAsString(original) + "\n"
419:       + "Error handler throwable: " + getStackTraceAsString(errorHandlerThrowable);
420: 
421:     LOGGER.error(msg);
422: 
423:     Response response = requestConstants.response.status(500);
424:     if (getServerConfig().isDevelopment()) {
425:       response.send(msg);
426:     } else {
427:       response.send();
428:     }
429:   }
