198:   public void next() {
199:     Handler handler = null;
200: 
201:     ChainIndex index = requestConstants.indexes.peek();
202:     while (handler == null) {
203:       if (index.hasNext()) {
204:         handler = index.next();
205:         if (handler.getClass().equals(ChainHandler.class)) {
206:           requestConstants.indexes.push(new ChainIndex(((ChainHandler) handler).getHandlers(), getContextRegistry(), false));
207:           index = requestConstants.indexes.peek();
208:           handler = null;
209:         }
210:       } else if (index.first) {
211:         handler = requestConstants.applicationConstants.end;
212:       } else {
213:         requestConstants.indexes.pop();
214:         index = requestConstants.indexes.peek();
215:       }
216:     }
217: 
218:     try {
219:       requestConstants.handler = handler;
220:       handler.handle(this);
221:     } catch (Throwable e) {
222:       if (e instanceof HandlerException) {
223:         throw (HandlerException) e;
224:       } else {
225:         throw new HandlerException(e);
226:       }
227:     }
228:   }
