285:     Function<Parser<?>, T> parserPredicate = parse.getOpts().isPresent()
286:       ?
287:       parser -> {
288:         if (parser.getOptsType().isInstance(parse.getOpts().get())) {
289:           Parser<O> cast = Types.cast(parser);
290:           return cast.parse(DefaultContext.this, body, parse);
291:         }
292:         return null;
293:       }
294:       :
295:       parser -> {
