361:   public void error(Throwable throwable) {
362:     ServerErrorHandler serverErrorHandler = get(ServerErrorHandler.class);
363:     throwable = unpackThrowable(throwable);
364: 
365:     ThrowableHolder throwableHolder = getRequest().maybeGet(ThrowableHolder.class).orElse(null);
366:     if (throwableHolder == null) {
367:       getRequest().add(ThrowableHolder.class, new ThrowableHolder(throwable));
368: 
369:       try {
370:         serverErrorHandler.error(this, throwable);
371:       } catch (Throwable errorHandlerThrowable) {
372:         onErrorHandlerError(serverErrorHandler, throwable, errorHandlerThrowable);
373:       }
374:     } else {
375:       onErrorHandlerError(serverErrorHandler, throwableHolder.getThrowable(), throwable);
376:     }
377:   }
