379:   private void onErrorHandlerError(ServerErrorHandler serverErrorHandler, Throwable original, Throwable errorHandlerThrowable) {
380:     String msg = "Throwable thrown by error handler " + serverErrorHandler + " while handling throwable\n"
381:       + "Original throwable: " + getStackTraceAsString(original) + "\n"
382:       + "Error handler throwable: " + getStackTraceAsString(errorHandlerThrowable);
383: 
384:     LOGGER.error(msg);
385: 
386:     Response response = requestConstants.response.status(500);
387:     if (getServerConfig().isDevelopment()) {
388:       response.send(msg);
389:     } else {
390:       response.send();
391:     }
392:   }
