35: public class ConfigDataReloadInformant implements ReloadInformant, Service {
36: 
37:   private static final Logger LOGGER = LoggerFactory.getLogger(ConfigDataReloadInformant.class);
38:   private static final Duration INTERVAL = Duration.ofSeconds(1);
39: 
40:   private final ConfigDataLoader loader;
41:   private final ObjectNode currentNode;
42: 
43:   private boolean changeDetected;
44:   private boolean stopped;
45: 
46:   public ConfigDataReloadInformant(ObjectNode currentNode, ConfigDataLoader loader) {
47:     this.currentNode = currentNode;
48:     this.loader = loader;
49:   }
50: 
51:   @Override
52:   public boolean shouldReload(Registry registry) {
53:     return changeDetected;
54:   }
55: 
56:   private void schedulePoll() {
57:     if (shouldStop()) {
58:       return;
59:     }
60: 
61:     final ExecController controller = Execution.current().getController();
62:     ScheduledExecutorService scheduledExecutorService = controller.getExecutor();
63: 
64:     Runnable poll = () ->
65:       controller.fork().start(e -> {
66:           if (shouldStop()) {
67:             return;
68:           }
69:           Blocking.get(loader::load)
70:             .onError(error -> {
71:               LOGGER.warn("failed to load config in order to check for changes", error);
72:               schedulePoll();
73:             })
74:             .then(newNode -> {
75:               if (currentNode.equals(newNode)) {
76:                 LOGGER.debug("No difference in configuration data");
77:                 schedulePoll();
78:               } else {
79:                 LOGGER.info("Configuration data difference detected; next request should reload");
80:                 changeDetected = true;
81:               }
82:             });
83:         }
84:       );
85: 
86:     scheduledExecutorService.schedule(poll, INTERVAL.getSeconds(), TimeUnit.SECONDS);
87:   }
88: 
89:   private boolean shouldStop() {
90:     return stopped || Execution.current().getController().getEventLoopGroup().isShuttingDown();
91:   }
92: 
93:   @Override
94:   public String toString() {
95:     return "configuration data reload informant";
96:   }
97: 
98:   @Override
99:   public void onStart(StartEvent event) throws Exception {
100:     schedulePoll();
101:   }
102: 
103:   @Override
104:   public void onStop(StopEvent event) throws Exception {
105:     stopped = true;
106:   }
