80:     final Handler next = context -> {
81:       calledNext = true;
82:       results.getLatch().countDown();
83:     };
84: 
85:     final RenderController renderController = (object, context) -> {
86:       rendered = object;
87:       latch.countDown();
88:     };
89: 
90:     Stopper stopper = () -> {
91:       throw new UnsupportedOperationException("stopping not supported while unit testing");
92:     };
