94:     ResponseTransmitter responseTransmitter = new ResponseTransmitter() {
95:       @Override
96:       public void transmit(HttpResponseStatus status, ByteBuf byteBuf) {
97:         sentResponse = true;
98:         body = new byte[byteBuf.readableBytes()];
99:         byteBuf.readBytes(body);
100:         byteBuf.release();
101:         eventController.fire(new DefaultRequestOutcome(request, new DefaultSentResponse(headers, new DefaultStatus(status)), Instant.now()));
102:         latch.countDown();
103:       }
104: 
105:       @Override
106:       public void transmit(HttpResponseStatus status, Path file) {
107:         sentFile = file;
108:         eventController.fire(new DefaultRequestOutcome(request, new DefaultSentResponse(headers, DefaultHandlingResult.this.status), Instant.now()));
109:         latch.countDown();
110:       }
111: 
112:       @Override
113:       public Subscriber<ByteBuf> transmitter(HttpResponseStatus status) {
114:         throw new UnsupportedOperationException("streaming not supported while unit testing");
115:       }
116:     };
117: 
118:     ForkController forkController = forkController.forkController(ForkController.class);
119:     Registry effectiveRegistry = Registry.single(Stopper.class, stopper).join(forkController);
120:     DefaultContext.ApplicationConstants applicationConstants = new DefaultContext.ApplicationConstants(effectiveRegistry, renderController, forkController, next);
121:     requestConstants = new DefaultContext.RequestConstants(
122:       applicationConstants, request, null, eventController.getRegistry()
123:     );
124:     Response response = new DefaultResponse(responseHeaders, forkController.get(ByteBufAllocator.class), responseTransmitter);
