401:   @ChannelHandler.Sharable
402:   private class ReloadHandler extends SimpleChannelInboundHandler<FullHttpRequest> {
403:     private ServerConfig lastServerConfig;
404:     private DefinitionBuild definitionBuild;
405:     private final Throttle reloadThrottle = Throttle.ofSize(1);
406: 
407:     private ChannelHandler inner;
408: 
409:     public ReloadHandler(DefinitionBuild definition) {
410:       super(false);
411:       this.definitionBuild = definition;
412:       this.lastServerConfig = definitionBuild.getServerConfig();
413:       try {
414:         this.inner = buildAdapter(definitionBuild);
415:       } catch (Exception e) {
416:         this.inner = null;
417:         serverRegistry = buildServerRegistry(lastServerConfig, r -> r);
418:       }
419:     }
420: 
421:     @Override
422:     protected void channelRead0(ChannelHandlerContext ctx, FullHttpRequest msg) throws Exception {
423:       execController.fork().start(e ->
424:           Promise.<ChannelHandler>of(f -> {
425:             boolean rebuild = false;
426: 
427:             if (inner == null || definitionBuild.error != null) {
428:               rebuild = true;
429:             } else {
430:               Optional<ReloadInformant> reloadInformant = serverRegistry.first(TypeToken.of(ReloadInformant.class), r -> r.shouldReload(serverRegistry) ? r : null);
431:               if (reloadInformant.isPresent()) {
432:                 LOGGER.warn("reload requested by '" + reloadInformant.get() + "'");
433:                 rebuild = true;
434:               }
435:             }
436: 
437:             if (rebuild) {
438:               Blocking.get(() -> {
439:                 definitionBuild = buildUserDefinition();
440:                 lastServerConfig = definitionBuild.getServerConfig();
441:                 return buildAdapter(definitionBuild);
442:               })
443:                 .wiretap(r -> {
444:                   if (r.isSuccess()) {
445:                     inner = r.getValue();
446:                   }
447:                 })
448:                 .mapError(this::buildErrorRenderingAdapter)
449:                 .result(f::accept);
450:             } else {
451:               f.success(inner);
452:             }
453:           })
454:             .throttled(reloadThrottle)
455:             .then(adapter -> Blocking.fork(() -> delegate(ctx, adapter, msg)))
456:       );
457:     }
458: 
459:     private NettyHandlerAdapter buildErrorRenderingAdapter(Throwable e) {
460:       try {
461:         return new NettyHandlerAdapter(serverRegistry, context -> context.error(e));
462:       } catch (Exception e1) {
463:         throw uncheck(e);
464:       }
465:     }
466: 
467:     private void delegate(ChannelHandlerContext ctx, ChannelHandler delegate, FullHttpRequest msg) {
468:       try {
469:         ctx.pipeline().remove("inner");
470:       } catch (Exception ignore) {
471:         // ignore
472:       }
473:       ctx.pipeline().addLast("inner", delegate);
474:       ctx.fireChannelRead(msg);
475:     }
476:   }
