66:     Registry userRegistry = buildUserRegistry(userRegistryFactory, baseRegistry);
67: 
68:     execController.setInterceptors(ImmutableList.copyOf(userRegistry.getAll(ForkInterceptor.class)));
69:     execController.setInitializers(ImmutableList.copyOf(userRegistry.getAll(ForkInitializer.class)));
