85:   public static Registry buildBaseRegistry(RatpackServer ratpackServer, ForkController execController, ServerConfig serverConfig) {
86:     ErrorHandler errorHandler = serverConfig.isDevelopment() ? new DefaultDevelopmentErrorHandler() : new DefaultProductionErrorHandler();
87: 
88:     RegistryBuilder baseRegistryBuilder;
89:     try {
90:       baseRegistryBuilder = Registry.builder()
91:         .add(ServerConfig.class, serverConfig)
92:         .add(ByteBufAllocator.class, PooledByteBufAllocator.DEFAULT)
93:         .add(ForkController.class, execController)
94:         .add(MimeTypes.class, new ActivationBackedMimeTypes())
95:         .add(PublicAddress.class, new DefaultPublicAddress(serverConfig.getPublicAddress(), serverConfig.getSSLContext() == null ? HTTP_SCHEME : HTTPS_SCHEME))
96:         .add(Redirector.class, new DefaultRedirector())
97:         .add(ClientErrorHandler.class, errorHandler)
98:         .add(ServerErrorHandler.class, errorHandler)
99:         .with(new DefaultFileRenderer().register())
100:         .with(new PromiseRenderer().register())
101:         .with(new PublisherRenderer().register())
102:         .with(new RenderableRenderer().register())
103:         .with(new CharSequenceRenderer().register())
104:         .with(new JsonRenderer().register())
105:         .add(FormParser.class, new FormParser())
106:         .add(Clock.class, Clock.systemDefaultZone())
107:         .add(JsonParser.class, new JsonParser())
108:         .add(RatpackServer.class, ratpackServer)
109:         .add(ObjectMapper.class, new ObjectMapper())
110:           // TODO remove Stopper, and just use RatpackServer instead (will need to update perf and gradle tests)
111:         .add(Stopper.class, () -> uncheck(() -> {
112:           ratpackServer.stop();
113:           return null;
114:         }))
115:         .add(HttpClient.class, HttpClient.httpClient(PooledByteBufAllocator.DEFAULT, serverConfig.getMaxContentLength()))
116:         .add(ServerSentEventStreamClient.class, ServerSentEventStreamClient.sseStreamClient(PooledByteBufAllocator.DEFAULT))
117:         .add(HealthCheckResultsRenderer.class, new HealthCheckResultsRenderer())
118:         .add(RequestId.Generator.class, new UuidBasedRequestIdGenerator());
119: 
120:       addConfigObjects(serverConfig, baseRegistryBuilder);
121:     } catch (Exception e) {
122:       // Uncheck because it really shouldn't happen
123:       throw uncheck(e);
124:     }
125: 
126:     if (serverConfig.isHasBaseDir()) {
127:       baseRegistryBuilder.add(FileSystemBinding.class, serverConfig.getBaseDir());
128:     }
129: 
130:     return baseRegistryBuilder.build();
131:   }
