133:   private static void addConfigObjects(ServerConfig serverConfig, RegistryBuilder baseRegistryBuilder) {
134:     for (ConfigObject<?> configObject : serverConfig.getRequiredConfig()) {
135:       addConfigObject(baseRegistryBuilder, configObject);
136:     }
137:   }
