112:   public static LaunchConfig createLaunchConfig(LaunchConfigData data) {
113:     Properties properties = data.getProperties();
114:     Map<String, String> envVars = data.getEnvVars();
115:     TypeCoercingProperties development = new TypeCoercingProperties(properties, data.getClassLoader());
116:     try {
117:       Class<HandlerFactory> handlerFactoryClass;
118:       handlerFactoryClass = development.asClass(HANDLER_FACTORY, HandlerFactory.class);
119:       if (handlerFactoryClass == null) {
120:         throw new LaunchException("No handler factory class specified (config property: " + HANDLER_FACTORY + ")");
121:       }
122: 
123:       int defaultPort = DEFAULT_PORT;
124:       if (envVars.containsKey(Environment.PORT)) {
125:         try {
126:           String stringValue = envVars.get(Environment.PORT);
127:           defaultPort = Integer.valueOf(stringValue);
128:         } catch (NumberFormatException e) {
129:           throw new LaunchException("Environment var '" + Environment.PORT + "' is not an integer", e);
130:         }
131:       }
132: 
133:       int port = development.asInt(PORT, defaultPort);
134:       InetAddress address = development.asInetAddress(ADDRESS);
135:       URI publicAddress = development.asURI(PUBLIC_ADDRESS);
136:       boolean development = development.development(Property.development, false);
137:       int threads = development.asInt(THREADS, DEFAULT_THREADS);
138:       List<String> indexFiles = development.asList(INDEX_FILES);
139:       InputStream sslKeystore = development.asStream(SSL_KEYSTORE_FILE);
140:       String sslKeystorePassword = development.asString(SSL_KEYSTORE_PASSWORD, "");
141:       int maxContentLength = development.asInt(MAX_CONTENT_LENGTH, DEFAULT_MAX_CONTENT_LENGTH);
142:       boolean timeResponses = development.development(TIME_RESPONSES, false);
143:       boolean compressResponses = development.development(COMPRESS_RESPONSES, false);
144:       long compressionMinSize = development.asLong(COMPRESSION_MIN_SIZE, DEFAULT_COMPRESSION_MIN_SIZE);
145:       List<String> compressionMimeTypeWhiteList = development.asList(COMPRESSION_MIME_TYPE_WHITE_LIST);
146:       List<String> compressionMimeTypeBlackList = development.asList(COMPRESSION_MIME_TYPE_BLACK_LIST);
147: 
148:       Map<String, String> otherProperties = new HashMap<>();
149:       PropertiesUtil.extractProperties("other.", properties, otherProperties);
150: 
151:       HandlerFactory handlerFactory;
152:       try {
153:         handlerFactory = handlerFactoryClass.newInstance();
154:       } catch (Exception e) {
155:         throw new LaunchException("Could not instantiate handler factory: " + handlerFactoryClass.getName(), e);
156:       }
157: 
158:       LaunchConfigBuilder launchConfigBuilder = LaunchConfigBuilder.baseDir(data.getBaseDir())
159:         .port(port)
160:         .address(address)
161:         .publicAddress(publicAddress)
162:         .development(development)
163:         .threads(threads)
164:         .maxContentLength(maxContentLength)
165:         .timeResponses(timeResponses)
166:         .compressResponses(compressResponses)
167:         .compressionMinSize(compressionMinSize)
168:         .compressionWhiteListMimeTypes(compressionMimeTypeWhiteList)
169:         .compressionBlackListMimeTypes(compressionMimeTypeBlackList)
170:         .indexFiles(indexFiles);
171: 
172:       if (sslKeystore != null) {
173:         try (InputStream stream = sslKeystore) {
174:           launchConfigBuilder.ssl(SSLContexts.sslContext(stream, sslKeystorePassword));
175:         }
176:       }
177: 
178:       return launchConfigBuilder
179:         .other(otherProperties)
180:         .build(handlerFactory);
181: 
182:     } catch (Exception e) {
183:       if (e instanceof LaunchException) {
184:         throw (LaunchException) e;
185:       } else {
186:         throw new LaunchException("Failed to create launch config with properties: " + properties.toString(), e);
187:       }
188:     }
189:   }
