191:   private static Path resourceToPath(URL resource) {
192:     URI uri = toUri(resource);
193: 
194:     String scheme = uri.getScheme();
195:     if (scheme.equals("file")) {
196:       return Paths.get(uri);
197:     }
198: 
199:     if (!scheme.equals("jar")) {
200:       throw new LaunchException("Cannot deal with class path resource url: " + uri);
201:     }
202: 
203:     String s = uri.toString();
204:     int separator = s.indexOf("!/");
205:     String entryName = s.substring(separator + 2);
206:     URI fileURI = URI.create(s.substring(0, separator));
207:     FileSystem fs;
208:     try {
209:       fs = FileSystems.newFileSystem(fileURI, Collections.<String, Object>emptyMap());
210:     } catch (IOException e) {
211:       throw uncheck(e);
212:     }
213:     return fs.getPath(entryName);
214:   }
215: 
216:   private static URI toUri(URL url) {
217:     try {
218:       return url.toURI();
219:     } catch (URISyntaxException e) {
220:       throw new LaunchException("Could not convert URL '" + url + "' to URI", e);
221:     }
222:   }
223: }
